package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/guardian") public class GuardianController{private final GuardianService s;public GuardianController(GuardianService s){this.s=s;}@PostMapping public ResponseEntity<GuardianDTO> create(@Valid @RequestBody GuardianDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<GuardianDTO> all(){return s.all();}@GetMapping("/{id}") public GuardianDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public GuardianDTO update(@PathVariable Long id,@Valid @RequestBody GuardianDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
